"""Frozen generation/review prompts. Reviewers never see each other's responses."""
import json
DOMAINS=('natural-number arithmetic','integer arithmetic','divisibility','algebraic identities','finite sums','lists and recursion','finite sets','Boolean logic','propositional logic','inequalities','elementary number theory','mixed algebraic structures')

def generation_prompt(index):
    domain=DOMAINS[index%len(DOMAINS)]
    return '''Create exactly one original, nontrivial mathematical theorem in DOMAIN, with a faithful natural-language statement and a complete Lean4 reference proof using Mathlib. This is candidate construction, not proof-repair evaluation. Avoid renamed/template repetitions, binomial-square identities, successor-addition laws, simple commutativity/associativity/zero identities, elementary distributivity specializations, and tautologies. Do not reproduce known benchmark items or claim independent validation. Use a single theorem, no new axioms/definitions, sorry, admit or placeholder English. Keep the complete JSON within1200 output tokens. Return only JSON with keys: nl_statement, expected_lean_statement (bare theorem declaration without :=), reference_proof (the complete same named theorem with := by proof), domain, category, family, difficulty (provisional1-5), imports (exactly ["Mathlib"]), originality_limitations. Do not add Markdown or prose.''' .replace('DOMAIN',domain)

def reviewer_prompt(candidate,history):
    subject={k:candidate[k] for k in ('nl_statement','expected_lean_statement','domain','category','family')}
    return '''You are an AI mathematical/semantic screener, not an independent human reviewer. Assess the paired English and exact Lean statement for mathematical correctness, semantic fidelity, quantifiers, domains/assumptions, boundary conditions, extra/missing premises, ambiguity, specialization/equivalence, family dependence and possible historical overlap. You do not see a reference proof, generation prompt, generator answer history or another review. The historical excerpts are a bounded lexical retrieval, not an exhaustive semantic oracle. Be conservative: unresolved critical concerns require UNCERTAIN or REJECT. Return JSON only: decision (ACCEPT/REJECT/UNCERTAIN), explanation, problems (list), unresolved_critical (list), confidence (0..1), historical_relationship, semantic_checks (object covering quantifiers/domains/assumptions/boundaries/premises/operators/ambiguity). Agreement is not proof of semantic truth.\nSUBJECT:\n'''+json.dumps(subject,ensure_ascii=False)+'\nRETRIEVED HISTORICAL STATEMENTS:\n'+json.dumps(history,ensure_ascii=False)
